     1	//! Which insured item a reported damage is a claim against.
     2	//!
     3	//! This is the office's matching rule, and it is a policy decision of its own:
     4	//! the MHPCO has to decide what a damage report names when a policy covers
     5	//! several items, and today it reads an `itemType` as naming the cover of that
     6	//! type the policy carries. It changes when the office revises how a report is
     7	//! read against a policy -- matching successive reports of one type to
     8	//! successive covers, refusing more reports of a type than the policy covers --
     9	//! independently of the clauses that then judge each damage's amount, and
    10	//! independently of the ceiling on what the settlement may total.
    11	
    12	use crate::{Damage, Item};
    13	
    14	/// The insured item a reported damage is matched to, if the policy covers one.
    15	///
    16	/// The MHPCO matches by item type alone: a report names a type, and the office
    17	/// looks for that type among the covers on the policy.
    18	pub(crate) fn matched_cover<'a>(insured: &'a [Item], damage: &Damage) -> Option<&'a Item> {
    19	    insured
    20	        .iter()
    21	        .find(|item| item.item_type == damage.item_type)
    22	}
===== src/settlement_limit.rs =====
     1	//! The ceiling the MHPCO puts on what a policy will ever pay out.
     2	//!
     3	//! This is the office's exposure limit. It changes when the MHPCO revises how
     4	//! far it will stand behind a policy -- a different multiple of the insurance
     5	//! sum, a different basis for that sum, a cap carried across successive claims
     6	//! -- independently of the clauses that judge any single damage, and
     7	//! independently of how the premium side surcharged the same items: premium
     8	//! modifiers never raise the cap.
     9	
    10	use crate::pricing::insurance_sum;
    11	use crate::{Item, Settlement};
    12	
    13	/// The total payout per policy is capped at twice its insurance sum.
    14	const CAP_MULTIPLE: i64 = 2;
    15	
    16	/// The most the office will ever pay out on a policy covering these items.
    17	fn policy_cap(items: &[Item]) -> i64 {
    18	    CAP_MULTIPLE * insurance_sum(items)
    19	}
    20	
    21	/// What the office actually settles once its exposure limit is applied to the
    22	/// amount the claim's clauses would otherwise pay. The MHPCO does not refuse a
    23	/// claim that outruns the cap; it pays up to what is left of the ceiling and
    24	/// reports how much of the policy's exposure remains. The cap covers the
    25	/// policy, not the claim, so earlier settlements have already spent part of it.
    26	pub(crate) fn settle_within_cap(
    27	    items: &[Item],
    28	    desired_payout: i64,
    29	    already_paid: i64,
    30	) -> Settlement {
    31	    let remaining = policy_cap(items) - already_paid;
    32	    let payout = desired_payout.min(remaining);
    33	    Settlement {
    34	        payout,
    35	        remaining_cap: remaining - payout,
    36	    }
    37	}
