     1	//! How a customer's standing with the MHPCO bears on the premium: the
     2	//! policy-wide modifiers the office grants or levies for loyalty, for a first
     3	//! insurance, and for a contract that follows an earlier one.
     4	//!
     5	//! This is the customer-relations side of the office's knowledge. It changes
     6	//! when the MHPCO courts or squeezes its customers -- a longer loyalty
     7	//! qualification, a deeper follow-up discount -- independently of how
     8	//! hazardous any insured item happens to be.
     9	
    10	use crate::Customer;
    11	
    12	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
    13	const LOYALTY_DISCOUNT: f64 = 0.20;
    14	const LOYALTY_YEARS: i64 = 2;
    15	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
    16	
    17	/// A long-standing customer has been with the MHPCO for at least two years.
    18	fn is_long_standing(customer: &Customer) -> bool {
    19	    customer.years_with_mhpco >= LOYALTY_YEARS
    20	}
    21	
    22	/// Long-standing customers are rewarded with a discount on the policy.
    23	fn loyalty_rate(customer: &Customer) -> f64 {
    24	    if is_long_standing(customer) {
    25	        -LOYALTY_DISCOUNT
    26	    } else {
    27	        0.0
    28	    }
    29	}
    30	
    31	/// Every contract after the customer's first is discounted.
    32	fn follow_up_contract_rate(previous_quotes: usize) -> f64 {
    33	    if previous_quotes > 0 {
    34	        -FOLLOW_UP_CONTRACT_DISCOUNT
    35	    } else {
    36	        0.0
    37	    }
    38	}
    39	
    40	/// Every quote insures its items for the first time, so the initial assessment
    41	/// surcharge is carried unconditionally: the MHPCO reads "first insurance" as
    42	/// the item's, not the customer's, so customer history never waives it.
    43	fn first_insurance_rate() -> f64 {
    44	    FIRST_INSURANCE_SURCHARGE
    45	}
    46	
    47	/// The net policy-wide modifier rate the customer's circumstances carry, as a
    48	/// share of the policy base premium. The MHPCO sums its policy-wide modifiers
    49	/// rather than compounding them, so each one contributes its own rate here.
    50	fn policy_modifier_rate(customer: &Customer, previous_quotes: usize) -> f64 {
    51	    first_insurance_rate() + loyalty_rate(customer) + follow_up_contract_rate(previous_quotes)
    52	}
    53	
    54	/// What the customer's standing adds to or takes off the policy base premium.
    55	pub(crate) fn standing_adjustment(
    56	    base: f64,
    57	    customer: &Customer,
    58	    previous_quotes: usize,
    59	) -> f64 {
    60	    base * policy_modifier_rate(customer, previous_quotes)
    61	}
===== src/pricing.rs =====
     1	//! The MHPCO price list: what each insurable item costs to cover, before any
     2	//! risk assessment or customer standing is taken into account.
     3	//!
     4	//! This is the catalog side of the office's knowledge. It changes when the
     5	//! MHPCO revises its prices or its building-block offer, independently of the
     6	//! underwriting rules that surcharge and discount a policy.
     7	
     8	use std::collections::BTreeMap;
     9	
    10	use crate::Item;
    11	
    12	const SWORD_BASE_PREMIUM: f64 = 100.0;
    13	const AMULET_BASE_PREMIUM: f64 = 60.0;
    14	const STAFF_BASE_PREMIUM: f64 = 80.0;
    15	const POTION_BASE_PREMIUM: f64 = 40.0;
    16	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
    17	const COMPONENT_BLOCK_SIZE: usize = 3;
    18	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
    19	
    20	const SWORD_INSURANCE_VALUE: i64 = 1000;
    21	const AMULET_INSURANCE_VALUE: i64 = 600;
    22	const STAFF_INSURANCE_VALUE: i64 = 800;
    23	const POTION_INSURANCE_VALUE: i64 = 400;
    24	const COMPONENT_INSURANCE_VALUE: i64 = 250;
    25	
    26	/// Components are the small insurable parts the MHPCO lists apart from main
    27	/// items: they are priced per component and may form building blocks.
    28	fn is_component(item: &Item) -> bool {
    29	    matches!(item.item_type.as_str(), "rune" | "moonstone")
    30	}
    31	
    32	/// The MHPCO price list: the base premium each insurable main item carries.
    33	/// Components are not priced here; they are priced per building block.
    34	///
    35	/// An item type the price list does not name is not yet refused -- the office
    36	/// has no rule for it on the books -- so it falls through to the sword price.
    37	fn main_item_base_premium(item: &Item) -> f64 {
    38	    match item.item_type.as_str() {
    39	        "amulet" => AMULET_BASE_PREMIUM,
    40	        "staff" => STAFF_BASE_PREMIUM,
    41	        "potion" => POTION_BASE_PREMIUM,
    42	        _ => SWORD_BASE_PREMIUM,
    43	    }
    44	}
    45	
    46	/// A building block of alike components is offered at a special base premium.
    47	fn component_group_base_premium(count: usize) -> f64 {
    48	    if count == COMPONENT_BLOCK_SIZE {
    49	        COMPONENT_BLOCK_BASE_PREMIUM
    50	    } else {
    51	        count as f64 * COMPONENT_BASE_PREMIUM
    52	    }
    53	}
    54	
    55	/// Components are alike when they are of the very same type: the MHPCO reads
    56	/// "3 alike components" strictly, so runes and moonstones never share a block.
    57	fn alike_component_kind(item: &Item) -> &str {
    58	    item.item_type.as_str()
    59	}
    60	
    61	/// The base premium of all components in a policy: components of the same kind
    62	/// are counted together so that their building block can apply.
    63	fn components_base_premium(items: &[Item]) -> f64 {
    64	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    65	    for item in items.iter().filter(|item| is_component(item)) {
    66	        *counts.entry(alike_component_kind(item)).or_default() += 1;
    67	    }
    68	    counts.into_values().map(component_group_base_premium).sum()
    69	}
    70	
    71	/// The base premium of all main items in a policy, straight from the price list.
    72	fn main_items_base_premium(items: &[Item]) -> f64 {
    73	    items
    74	        .iter()
    75	        .filter(|item| !is_component(item))
    76	        .map(main_item_base_premium)
    77	        .sum()
    78	}
    79	
    80	/// The policy base premium: the sum of the base premiums of all insured items.
    81	pub(crate) fn policy_base_premium(items: &[Item]) -> f64 {
    82	    main_items_base_premium(items) + components_base_premium(items)
    83	}
    84	
    85	/// The base premium an item-specific modifier is measured against: the item's
    86	/// own listed price, which for a component is the per-component premium.
    87	pub(crate) fn item_base_premium(item: &Item) -> f64 {
    88	    if is_component(item) {
    89	        COMPONENT_BASE_PREMIUM
    90	    } else {
    91	        main_item_base_premium(item)
    92	    }
    93	}
    94	
    95	/// The MHPCO price list: what each insurable item is insured for. Unlike the
    96	/// premium, the insurance value knows nothing of building blocks -- three
    97	/// alike components are insured for three times a component's value.
    98	fn item_insurance_value(item: &Item) -> i64 {
    99	    if is_component(item) {
   100	        return COMPONENT_INSURANCE_VALUE;
   101	    }
   102	    match item.item_type.as_str() {
   103	        "amulet" => AMULET_INSURANCE_VALUE,
   104	        "staff" => STAFF_INSURANCE_VALUE,
   105	        "potion" => POTION_INSURANCE_VALUE,
   106	        _ => SWORD_INSURANCE_VALUE,
   107	    }
   108	}
   109	
   110	/// The insurance sum of a policy: the sum of its items' insurance values.
   111	pub(crate) fn insurance_sum(items: &[Item]) -> i64 {
   112	    items.iter().map(item_insurance_value).sum()
   113	}

mod coverage;
mod pricing;
mod reimbursement;
mod risk;
mod settlement_limit;
mod standing;

use coverage::matched_cover;
use pricing::policy_base_premium;
use reimbursement::damage_reimbursement;
use risk::item_risk_surcharges;
use settlement_limit::settle_within_cap;
use standing::standing_adjustment;

pub struct Customer {
    pub years_with_mhpco: i64,
}

pub struct Item {
    pub item_type: String,
    pub material: String,
    pub cursed: bool,
    pub enchantment: i64,
}

const PROCESSING_FEE: i64 = 5;

pub struct Damage {
    pub item_type: String,
    pub amount: i64,
}

pub struct Settlement {
    pub payout: i64,
    pub remaining_cap: i64,
}

pub struct Policy<'a> {
    insured: &'a [Item],
    paid_out: i64,
}

impl<'a> Policy<'a> {
    pub fn insuring(items: &'a [Item]) -> Self {
        Policy {
            insured: items,
            paid_out: 0,
        }
    }

    /// A settlement totals what the office reimburses for each damage the
    /// incident reported.
    pub fn claim(&mut self, damages: &[Damage]) -> Settlement {
        let reimbursed: f64 = damages
            .iter()
            .map(|damage| damage_reimbursement(damage, matched_cover(self.insured, damage)))
            .sum();
        let settlement = settle_within_cap(
            self.insured,
            round_payout_in_mhpco_favor(reimbursed),
            self.paid_out,
        );
        self.paid_out += settlement.payout;
        settlement
    }
}

/// A premium is rounded in the MHPCO's favor, which for money the customer
/// owes the office means upwards.
fn round_premium_in_mhpco_favor(premium: f64) -> i64 {
    premium.ceil() as i64
}

/// A payout is rounded in the MHPCO's favor, which for money the office owes
/// the claimant means downwards. Only the settlement total is rounded; the
/// reimbursements it sums are carried as fractions.
fn round_payout_in_mhpco_favor(payout: f64) -> i64 {
    payout.floor() as i64
}

/// How the MHPCO's two kinds of modifier reach the premium: policy-wide
/// modifiers scale the policy base premium, while item-specific modifiers are
/// measured against their own item's base premium and are added alongside, so
/// a curse never surcharges the rest of the policy.
fn premium_before_fee(customer: &Customer, items: &[Item], previous_quotes: usize) -> f64 {
    let base = policy_base_premium(items);
    base + standing_adjustment(base, customer, previous_quotes) + item_risk_surcharges(items)
}

pub fn quote(customer: &Customer, items: &[Item], previous_quotes: usize) -> i64 {
    let premium = premium_before_fee(customer, items, previous_quotes);
    round_premium_in_mhpco_favor(premium) + PROCESSING_FEE
}

#[cfg(test)]
mod tests {
    use super::*;

    /// An insured item of the given type, plain in every respect the MHPCO
    /// judges: ordinary material, uncursed, unenchanted. Each test names only
    /// the properties its own rule turns on.
    fn an_item(item_type: &str) -> ItemBuilder {
        ItemBuilder {
            item_type: item_type.to_string(),
            material: "steel".to_string(),
            cursed: false,
            enchantment: 0,
        }
    }

    struct ItemBuilder {
        item_type: String,
        material: String,
        cursed: bool,
        enchantment: i64,
    }

    impl ItemBuilder {
        fn made_of(mut self, material: &str) -> Self {
            self.material = material.to_string();
            self
        }

        fn cursed(mut self) -> Self {
            self.cursed = true;
            self
        }

        fn enchanted_to(mut self, level: i64) -> Self {
            self.enchantment = level;
            self
        }

        fn build(self) -> Item {
            Item {
                item_type: self.item_type,
                material: self.material,
                cursed: self.cursed,
                enchantment: self.enchantment,
            }
        }
    }

    #[test]
    fn empty_item_list_costs_only_the_processing_fee() {
        let customer = Customer { years_with_mhpco: 0 };
        assert_eq!(quote(&customer, &[], 0), 5);
    }

    #[test]
    fn plain_sword_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [an_item("sword").build()];
        assert_eq!(quote(&customer, &items, 0), 115);
    }

    #[test]
    fn plain_amulet_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [an_item("amulet").build()];
        assert_eq!(quote(&customer, &items, 0), 71);
    }

    #[test]
    fn plain_staff_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [an_item("staff").build()];
        assert_eq!(quote(&customer, &items, 0), 93);
    }

    #[test]
    fn plain_potion_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [an_item("potion").build()];
        assert_eq!(quote(&customer, &items, 0), 49);
    }

    #[test]
    fn single_rune_uses_the_component_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [an_item("rune").build()];
        assert_eq!(quote(&customer, &items, 0), 33);
    }

    #[test]
    fn single_moonstone_uses_the_component_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [an_item("moonstone").build()];
        assert_eq!(quote(&customer, &items, 0), 33);
    }

    #[test]
    fn two_runes_cost_fifty() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [
            an_item("rune").build(),
            an_item("rune").build(),
        ];
        assert_eq!(quote(&customer, &items, 0), 60);
    }

